const ORIENT_T = new Set(['EA888', 'DAZA', 'VR6', 'H22', 'J35', 'C30', '2GR', 'G16E', '4B11', 'M139', 'B18C', '3SGTE']);
const ORIENT_TL = new Set(['K24', 'K20C1', 'K20A', '4G63', 'EB23', 'Hayabusa', 'SR20DET', 'KA24', '4AGE']);
export function engineDims(e) {
  const d = ENGINE_DIMS[e.code] || CFG_DIMS[e.cfg] || CFG_DIMS.I4;
  const orient = e.cfg === 'EV' ? 'TL' : ORIENT_T.has(e.code) ? 'T' : ORIENT_TL.has(e.code) ? 'TL' : 'L';
  return { L: d[0], W: d[1], H: d[2], orient };
}

export const CARS = RAW.map(r => {
  const [id, make, model, years, price, body, layout, drive, mass, wb, L, W, H, wdF, e, t, a, w, swaps, color, tireMu, awdSplit] = r;
  return {
    id, make, model, years, price, body, layout, drive, mass, wb: wb / 1000, L: L / 1000, W: W / 1000, H: H / 1000, wdF,
    engine: { code: e[0], name: e[1], cfg: e[2], hp: e[3], tq: e[4], redline: e[5], asp: e[6], mass: e[7] ?? ENGINE_MASS[e[2]] },
    trans: { type: t[0], gears: t[1], final: t[2], maxTq: transMaxTq(t[0], e[4]) },
    aero: { cd: a[0], A: a[1], cl: a[2] },
    wheel: { bolt: w[0], min: w[1], max: w[2], dia: w[3], width: w[4], tireW: w[5], tireA: w[6], maxTire: w[7] },
    swaps, color, tireMu, awdSplit: awdSplit ?? 0.4,
  };
});
// bolt-in kits that exist for cars the first list left empty / short (adapter mounts + harness off the shelf)
const KIT_ADD = {
  viper_acr: ['LS7', 'LSX454', 'Hemi392', 'Hellephant'], viper_gts: ['Hemi392'],
  hellcat: ['Hellephant', 'Hemi392', 'LS7', 'LT4'], gt350: ['Predator', 'CoyoteG3', 'Godzilla', 'LS3'],
  c8: ['LT6', 'LT2'], g80: ['B58', 'S55'], f80m3: ['S55'], gt3_991: ['MA175', '9A2TT', 'Mezger'], gt4_718: ['MA175', 'Mezger', '9A2TT'],
  m3p: ['Plaid'], gti_mk7: ['DAZA', 'EA888', 'VR6'], golfr: ['DAZA', 'EA888'], elantra_n: ['K20C1'], fl5: ['K24', 'K20A'],
  wrx_vb: ['EJ257', 'EJ207', 'FA24DIT'], nc1: ['J35', 'C30'], raptor: ['Godzilla', 'CoyoteG3'], focusrs: ['EB23'],
  grcorolla: ['K20C1'], r35: ['VR38'], camaro_ss: ['LT1', 'LS7'], c6z06: ['LS3', 'LT1', 'LSX454'], huracan_evo: ['AudiV10'], r8v10: ['AudiV10'],
};
for (const c of CARS) for (const k of KIT_ADD[c.id] || []) if (!c.swaps.includes(k) && k !== c.engine.code) c.swaps.push(k);
// engine orientation in the chassis: transverse (east-west, with a transaxle) or longitudinal
const TRANSVERSE_CARS = new Set(['evo6', 'evo9', 'evox', 'golfr', 'focusrs', 'grcorolla', 'nsx_na1', 'elise_s2']);
for (const c of CARS) {
  c.transverse = c.drive === 'FWD' || TRANSVERSE_CARS.has(c.id);
  const st = engineDims({ cfg: c.engine.cfg, code: c.engine.code });
  // engine bay (mm): the stock engine plus working room, or what the body's width / wheelbase / height leaves
  if (c.layout === 'F') c.bay = c.transverse
    ? { across: Math.max(st.L * 1.08, c.W * 1000 * 0.42), fore: Math.max(st.W * 1.1, 700), H: Math.max(st.H * 1.05, c.H * 1000 * 0.55) }
    : { L: Math.max(st.L * 1.08, c.wb * 1000 * 0.30), W: Math.max(st.W * 1.06, c.W * 1000 * 0.44), H: Math.max(st.H * 1.05, c.H * 1000 * 0.55) };
  else c.bay = { L: Math.max(st.L * 1.12, 760), W: Math.max(st.W * 1.08, c.W * 1000 * 0.45), H: Math.max(st.H * 1.08, c.H * 1000 * 0.52) };
}
