// ---------- simple parts ----------
// Each part: { id, cat, brand, name, price, mass, pos, desc, ...effects, check(car, ctx) -> [level,msg] | null }
const isEV = ctx => ctx.engine.asp === 'ev';
const boosted = ctx => ctx.engine.asp === 'turbo' || ctx.engine.asp === 'sc';
const noEV = (ctx) => isEV(ctx) ? ['error', 'Not applicable to an electric drivetrain'] : null;

export const PARTS = [];
const P = (o) => PARTS.push(o);

// Forced induction
const FI = (id, brand, name, price, mass, cfgs, asp, hp, tq, extra = {}) => P({
  id, cat: 'forced', brand, name, price, mass, pos: 'f', fi: { asp, hp, tq, spool: extra.spool, kind: extra.kind || (asp === 'turbo' ? 'turbo' : 'centrifugal') }, desc: extra.desc,
  check: (car, ctx) => {
    if (isEV(ctx)) return ['error', 'Electric motors cannot be boosted'];
    if (extra.needs === 'na' && ctx.engine.asp !== 'na') return ['error', `Engine is already ${ctx.engine.asp === 'sc' ? 'supercharged' : 'turbocharged'}`];
    if (extra.needs === 'turbo' && ctx.engine.asp !== 'turbo') return ['error', 'Requires a factory-turbo engine'];
    if (extra.needs === 'sc' && ctx.engine.asp !== 'sc') return ['error', 'Requires a supercharged engine'];
    if (cfgs && !cfgs.includes(ctx.engine.cfg)) return ['error', `Kit is for ${cfgs.join('/')} engines (yours: ${ctx.engine.cfg})`];
    return null;
  },
  req: extra.req,
});
