// ---------- engine internals ----------
// boostTol: multiplies what the bottom end survives (stock ≈ 1.75× stock power)
const noEVi = (c, x) => noEV(x);
const ROT = x => /^R\d$/.test(x.engine.cfg);
// piston-engine hardware: a rotary has no pistons, crank, valves, cams or head
const pistonOnly = (c, x) => noEV(x) || (ROT(x) ? ['error', 'Rotary engine — no pistons, crank, valves or head (see the rotary internals)'] : null);
const rotaryOnly = (c, x) => noEV(x) || (ROT(x) ? null : ['error', 'Rotary engines only']);
const IN = o => P({ cat: 'internals', pos: 'f', check: noEVi, ...o });
IN({ check: pistonOnly, id: 'pistons', brand: 'Wiseco / Manley', name: 'Forged pistons + H-beam rods', price: 3400, mass: -1, hpNA: 0.01, hpBoost: 0.02, boostTol: 1.0, rev: 200, desc: 'Forged bottom end: survives about 2.75× stock power under boost.' });
