TR('dragseq', 'Liberty / G-Force', 'Drag-spec sequential + quad-disc clutch (3200 Nm)', 26500, -6, 3200, ['MT', 'SEQ'], { shiftTime: 0.05, newType: 'SEQ', inertiaMul: 0.8 });
