// Transmission swaps: a different gearbox (gear count / type / strength). Gearing is scaled to keep a sensible first
// gear for the car's tires. Longitudinal boxes don't fit a transverse FWD layout unless the car is converted.
const TX = (id, brand, name, price, mass, type, gears, rating, mount, extra = {}) => P({ id, cat: 'gearbox', brand, name, price, mass, pos: 'c', tx: { type, gears, rating, mount, ...extra },
  check: (c, x) => isEV(x) ? ['error', 'Electric drive units have a fixed single-speed reduction'] : (mount === 'long' && x.drive === 'FWD') ? ['error', 'Longitudinal gearbox — a transverse FWD car needs a RWD or AWD conversion first'] : (mount === 'trans' && x.drive === 'RWD') ? ['error', 'Transverse gearbox — fits front-engine FWD / AWD layouts, not RWD'] : null });
TX('tx_t56', 'Tremec', 'T56 Magnum 6-speed manual', 5200, 6, 'MT', [2.66, 1.78, 1.30, 1.00, 0.80, 0.63], 950, 'long');
TX('tx_cd009', 'Nissan', 'CD009 6-speed manual (350Z / 370Z)', 3400, 0, 'MT', [3.79, 2.32, 1.62, 1.27, 1.00, 0.79], 650, 'long');
TX('tx_zf8', 'ZF', '8HP 8-speed automatic + standalone TCU', 4800, 12, 'AT', [4.71, 3.14, 2.11, 1.67, 1.29, 1.00, 0.84, 0.67], 1000, 'long', { shiftTime: 0.12 });
TX('tx_10r', 'Ford', '10R80 10-speed automatic', 5600, 15, 'AT', [4.70, 2.99, 2.15, 1.80, 1.52, 1.28, 1.00, 0.85, 0.69, 0.64], 1100, 'long', { shiftTime: 0.11 });
TX('tx_dct7', 'Getrag', '7-speed dual-clutch (DCT) swap', 9800, 4, 'DCT', [3.91, 2.17, 1.48, 1.12, 0.89, 0.75, 0.63], 800, 'long', { shiftTime: 0.06 });
TX('tx_seq6', 'Quaife', '6-speed sequential dog box', 17500, -8, 'SEQ', [2.86, 2.06, 1.62, 1.33, 1.14, 0.98], 1200, 'long', { shiftTime: 0.05 });
TX('tx_k6', 'Honda', 'K-series 6-speed manual (transverse)', 2400, 0, 'MT', [3.27, 2.13, 1.52, 1.15, 0.92, 0.75], 520, 'trans');
TX('tx_dq', 'VW', 'DQ381 7-speed DSG (transverse)', 5200, 6, 'DCT', [3.40, 2.75, 1.65, 1.05, 0.83, 0.86, 0.70], 600, 'trans', { shiftTime: 0.06 });
TX('tx_seqfwd', 'Sadev', 'SL75 6-speed sequential (transverse)', 16500, -6, 'SEQ', [2.92, 2.12, 1.67, 1.37, 1.15, 0.99], 750, 'trans', { shiftTime: 0.05 });

// Drivetrain conversions: change which wheels are driven
const DT = (id, brand, name, price, mass, drive, split, from, desc, extra = {}) => P({ id, cat: 'drivetrain', brand, name, price, mass, pos: 'c', dt: { drive, split, ...extra }, desc,
  check: (c) => !from.includes(c.drive) ? ['error', `Converts ${from.join('/')} cars (this one is ${c.drive})`] : (extra.frontEngine && c.layout !== 'F') ? ['error', 'Needs a front-engine car'] : extra.warn ? ['warn', extra.warn] : null });
DT('dt_fwd2rwd', 'Fab shop', 'FWD → RWD conversion', 12500, 45, 'RWD', 0, ['FWD'], 'Engine turned longitudinal, rear subframe with diff, driveshaft and a cut & widened tunnel. Pair it with a longitudinal gearbox.', { frontEngine: true });
DT('dt_awd2rwd', 'Generic', 'AWD → RWD conversion (front axle deleted)', 900, -28, 'RWD', 0, ['AWD'], 'Front driveshafts and transfer output removed, centre diff locked to the rear. Lighter, drifts, less traction.');
DT('dt_2awd', 'Fab shop', 'AWD conversion (40:60 split)', 14500, 70, 'AWD', 0.4, ['FWD', 'RWD'], 'Transfer case, front/rear diffs, extra driveshafts and custom mounts: all four wheels driven, biased to the rear.');
DT('dt_awdfront', 'Haldex-style', 'Front-biased AWD conversion (60:40)', 9800, 55, 'AWD', 0.6, ['FWD'], 'Rear diff, prop shaft and an electronically coupled centre: a FWD car that also drives the rear.');
DT('dt_4x4', 'Off-road', 'Part-time 4×4 with locked centre (50:50)', 9000, 90, 'AWD', 0.5, ['FWD', 'RWD', 'AWD'], 'Transfer case with a locked centre and low range. Unbeatable traction, but it binds and scrubs in tight tarmac corners.', { frontEngine: true, lockedCentre: true, warn: 'Locked centre diff scrubs the tires in tight corners on tarmac' });

