export const WHEELS = [];
for (const [mid, brand, name, type, style, spokes, color, base, mass, dias, bolts] of WHEEL_MODELS) {
  const truck = bolts === TRUCK;
  for (const d of dias) {
    const wmin = truck ? 8 : Math.max(5, Math.round(d * 0.37 * 2) / 2);
    const wmax = truck ? 10 : Math.min(12, Math.round(d * 0.58 * 2) / 2);
    for (let w = wmin; w <= wmax; w += 0.5) {
      const price = Math.round(base * (1 + (d - 17) * 0.13 + (w - 8) * 0.05) / 5) * 5 * 4;
      const m = +(mass * (1 + (d - 17) * 0.11 + (w - 8) * 0.06)).toFixed(1);
      WHEELS.push({ id: `w_${mid}_${d}x${w}`, cat: 'wheels', model: mid, brand, name: `${name} ${d}x${w}`, type, style, spokes, color, dia: d, width: w, bolts, price, wheelMass: m, truck });
    }
  }
}
export const WHEEL_BY_ID = Object.fromEntries(WHEELS.map(w => [w.id, w]));

// ---------- tires (generated) ----------
// [id, brand, name, type, mu, latMul, longMul, kp, ap, pricePerTire@225/45R17, rr, massMul, rims, widths, diaRangeInches, treadwear]
const TIRE_MODELS = [
  ['eco', 'Generic', 'Economy Touring', 'Budget all-season', 0.80, 1, 1, 0.11, 0.16, 85, 0.011, 1.0, [13, 18], [155, 245], [21, 28.5], 600],
  ['defender', 'Michelin', 'Defender2', 'Touring all-season', 0.86, 1, 1, 0.10, 0.15, 165, 0.010, 1.0, [14, 20], [175, 275], [22, 30], 800],
  ['dws06', 'Continental', 'ExtremeContact DWS06+', 'UHP all-season', 0.94, 1, 1, 0.10, 0.14, 190, 0.011, 1.0, [15, 21], [195, 305], [22, 29], 560],
  ['ps4s', 'Michelin', 'Pilot Sport 4S', 'Max performance summer', 1.03, 1, 1, 0.09, 0.13, 275, 0.012, 1.0, [17, 22], [205, 335], [23, 29], 300],
  ['rt660', 'Falken', 'Azenis RT660', '200TW extreme summer', 1.10, 1, 1, 0.085, 0.115, 185, 0.012, 1.05, [15, 19], [195, 295], [22, 28], 200],
  ['re71rs', 'Bridgestone', 'Potenza RE-71RS', '200TW extreme summer', 1.13, 1, 1, 0.085, 0.11, 245, 0.012, 1.05, [15, 20], [195, 315], [22, 28], 200],
  ['a052', 'Yokohama', 'Advan A052', 'Track & street', 1.18, 1, 1, 0.08, 0.105, 280, 0.013, 1.05, [15, 20], [195, 315], [22, 28], 200],
  ['trofeor', 'Pirelli', 'P Zero Trofeo R', 'Track & street', 1.22, 1, 1, 0.08, 0.10, 420, 0.013, 1.0, [18, 21], [235, 335], [24, 28.5], 60],
  ['r7', 'Hoosier', 'R7', 'DOT R-compound', 1.32, 1, 1, 0.075, 0.095, 390, 0.014, 1.0, [13, 20], [195, 345], [21, 28], 40],
  ['slick', 'Hoosier', 'Racing slick', 'Non-DOT slick (track only)', 1.48, 1, 1, 0.07, 0.09, 450, 0.014, 0.95, [13, 20], [205, 355], [21, 28], 0],
  ['etsr', 'Mickey Thompson', 'ET Street R', 'Drag radial', 1.00, 0.82, 1.45, 0.12, 0.16, 330, 0.014, 1.1, [15, 20], [235, 335], [24, 29], 40],
  ['ko2', 'BFGoodrich', 'All-Terrain T/A KO2', 'All-terrain', 0.78, 1, 1, 0.14, 0.19, 245, 0.018, 1.6, [15, 20], [235, 355], [29, 37], 500],
];
const ASPECTS = [25, 30, 35, 40, 45, 50, 55, 60, 65, 70, 75];
export const tireDiaIn = (w, a, rim) => rim + 2 * w * a / 100 / 25.4;
export function tireMass(w, a, rim, mul = 1) { return +(9.5 * (w / 225) * Math.pow(tireDiaIn(w, a, rim) / 25, 1.6) * mul).toFixed(1); }

export const TIRES = [];
for (const [mid, brand, name, type, mu, lat, lng, kp, ap, base, rr, massMul, rims, widths, drange, tw] of TIRE_MODELS) {
  for (let rim = rims[0]; rim <= rims[1]; rim++) {
    for (let w = widths[0]; w <= widths[1]; w += 10) {
      for (const a of ASPECTS) {
        const D = tireDiaIn(w, a, rim);
        if (D < drange[0] || D > drange[1]) continue;
        if (a > 50 && rim >= 19 && mid !== 'ko2') continue;
        const price = Math.round(base * (1 + (rim - 17) * 0.12 + (w - 225) / 220) / 5) * 5 * 4;
        TIRES.push({ id: `t_${mid}_${w}_${a}_${rim}`, cat: 'tires', model: mid, brand, name: `${name} ${w}/${a}R${rim}`, type, mu, lat, lng, kp, ap, rr, width: w, aspect: a, rim, dia: D, price, tireMass: tireMass(w, a, rim, massMul), treadwear: tw });
      }
    }
  }
}
export const TIRE_BY_ID = Object.fromEntries(TIRES.map(t => [t.id, t]));

export function stockWheel(car) {
  const d = car.wheel.dia, w = car.wheel.width;
  return { id: 'stock', cat: 'wheels', stock: true, brand: car.make, name: `OEM ${d}x${w}`, style: car.body === 'truck' ? 'spoke' : 'twin', spokes: 5, color: '#b9bcc0', dia: d, width: w, bolts: [car.wheel.bolt], price: 0, wheelMass: +(7.6 * (1 + (d - 17) * 0.11 + (w - 8) * 0.06) * (car.body === 'truck' ? 1.6 : 1.12)).toFixed(1) };
}
export function stockTire(car) {
  const { tireW: w, tireA: a, dia: rim } = car.wheel;
  return { id: 'stock', cat: 'tires', stock: true, brand: 'OEM', name: `OEM ${w}/${a}R${rim}`, type: 'Factory fitment', mu: car.tireMu, lat: 1, lng: 1, kp: 0.09, ap: 0.13, rr: car.body === 'truck' ? 0.017 : 0.012, width: w, aspect: a, rim, dia: tireDiaIn(w, a, rim), price: 0, tireMass: tireMass(w, a, rim, car.body === 'truck' ? 1.6 : 1) };
}

export function totalPartCount() {
  return PARTS.length + WHEELS.length + TIRES.length + Object.keys(SWAPS).length;
}
